@js:
let push = (arr, title, url, basis) => arr.push({
  title,
  url,
  style: { 
    layout_flexBasisPercent: basis,
    layout_flexGrow: 1
  }
});

let category = [
  { name: "玄幻奇幻", path: "xuanhuan" },
  { name: "言情小说", path: "yanqing" },
  { name: "武侠仙侠", path: "xianxia" },
  { name: "军事历史", path: "lishi" },
  { name: "科幻未来", path: "wangyou" },
  { name: "灵异玄幻", path: "lingyi" },
  { name: "百合剧情", path: "baihe" },
  { name: "奇幻冒险", path: "fanatsy" },
  { name: "电视剧", path: "drama" },
  { name: "经典小说", path: "classicbook" }
];

let filter = [
  { label: "最新", value: "new" },
  { label: "日榜", value: "day" },
  { label: "周榜", value: "week" },
  { label: "总榜", value: "total" },
  { label: "完结", value: "isFinished" }
];

JSON.stringify(category.reduce((acc, { name, path }) => {
  push(acc, name, "", 1);
  filter.forEach(({ label, value }) => {
    push(acc, label, `@js:getUrl("/novel/list", "find", null, null, "${value}", "${path}")`, 0.16);
  });
  return acc;
}, []))

